export type ParsedReclaimAirdropInstruction<
  TProgram extends string = typeof LEVERMEME_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    admin: TAccountMetas[0];
    protocol: TAccountMetas[1];
    campaign: TAccountMetas[2];
    leverMint: TAccountMetas[3];
    airdropVault: TAccountMetas[4];
    destination: TAccountMetas[5];
    leverProgram: TAccountMetas[6];
  };
  data: ReclaimAirdropInstructionData;
};

export function parseReclaimAirdropInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedReclaimAirdropInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 7,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      admin: getNextAccount(),
      protocol: getNextAccount(),
      campaign: getNextAccount(),
      leverMint: getNextAccount(),
      airdropVault: getNextAccount(),
      destination: getNextAccount(),
      leverProgram: getNextAccount(),
    },
    data: getReclaimAirdropInstructionDataDecoder().decode(instruction.data),
  };
}
